topics.spacy_pattern:
# spaCy Matcher Pattern for Near Future (Futur Proche)
pattern_futur_proche = [
    {
        "POS": "VERB",
        "LEMMA": "aller",
        "MORPH": {"IN": ["Mood=Ind", "Tense=Pres", "VerbForm=Fin"]}
    },
    {
        "POS": "ADV",
        "OP": "*"
    },
    {
        "POS": "VERB",
        "MORPH": "VerbForm=Inf"
    }
]

# spaCy Matcher Pattern for Post-nominal Adjectives
pattern_postnominal_adj = [
    {
        "POS": "NOUN"
    },
    {
        "POS": "ADJ"
    }
]

# spaCy Matcher Pattern for Pre-nominal BANGS Adjectives
pattern_bangs_adj = [
    {
        "POS": "ADJ",
        "LEMMA": {"IN": [
            "beau", "joli", "jeune", "vieux", "nouveau", "bon", "mauvais",
            "grand", "petit", "gros", "long", "court", "haut"
        ]}
    },
    {
        "POS": "NOUN"
    }
]

# spaCy Matcher Pattern for Adverb Placement in Compound Tenses
pattern_adverb_placement = [
    {
        "POS": "AUX"
    },
    {
        "POS": "ADV",
        "TEXT": {"REGEX": ".*ment$"}
    },
    {
        "POS": "VERB",
        "MORPH": "VerbForm=Part"
    }
]

# spaCy Matcher Pattern for Comparative Structure
pattern_comparative = [
    {
        "POS": "ADV",
        "LEMMA": {"IN": ["plus", "moins", "aussi"]}
    },
    {
        "POS": "ADJ"
    },
    {
        "POS": "SCONJ",
        "LEMMA": "que"
    }
]

# spaCy Matcher Pattern for Relative Superlative
pattern_superlative = [
    {
        "POS": "DET",
        "LEMMA": {"IN": ["le", "la", "les"]}
    },
    {
        "POS": "ADV",
        "LEMMA": {"IN": ["plus", "moins"]}
    },
    {
        "POS": "ADJ"
    }
]
